    mx_niuqu: {
        audio: 'ext:梦隐/Skill dubbing:2',
        trigger: {
            global: 'useCardAfter',
        },
        filter(event, player) {
            if (event.parent.name == 'mx_niuqu') {
                return false;
            }
            if (event.player == player) {
                return false;
            }
            if (event.targets.length <= 1 || !event.card) {
                return false;
            }
            if (!event.targets.includes(player)) {
                return false;
            }
            let card = game.createCard({ name: event.card.name, suit: event.card.suit, number: event.card.number, nature: event.card.nature });
            for (const i of event.targets) {
                if (!i.isAlive()) {
                    return false;
                }
            }
            return true;
        },
        check(event, player) {
            const list1 = [];
            const list2 = [];
            let num = get.attitude(player, event.player);
            const players = game.filterPlayer();
            if (event.card.name == 'wanjian' || event.card.name == 'nanman') {
                players.remove(event.player);
            }
            for (let i of players) {
                if (get.attitude(player, i) > 0) {
                    list1.push(i);
                } else if (get.attitude(player, i) < 0) {
                    list2.push(i);
                }
            }
            if (list2 > list1 && (event.card.name == 'wanjian' || event.card.name == 'nanman')) {
                return 1;
            }
            if ((list1 > list2 && event.card.name == 'taoyuan') || event.card.name == 'wugu') {
                return 1;
            }
            if (event.player.hasSkill('huogong2') && num < 0) {
                return 1;
            }
            if (event.card.name == 'shunshou' && num > 0) {
                return 1;
            }
            if ((event.card.name == 'tiesuo' || event.card.name == 'guohe' || event.card.name == 'jiu' || event.card.name == 'jiedao') && num < 0) {
                return 1;
            }
            if (event.card.name == 'sha') {
                if (get.attitude(player, player.next) < 0 && event.targets.includes(player.next)) {
                    if (player.countCards('h', 'shan') || player.getEquip(2)) {
                        return 1;
                    } else if (player.next.hp == 1 && player.hp > player.next.hp) {
                        return 1;
                    } else {
                        return 0;
                    }
                }
                if (get.attitude(player, player.previous) < 0 && event.targets.includes(player.previous)) {
                    if (player.countCards('h', 'shan') || player.getEquip(2)) {
                        return 1;
                    } else if (player.previous.hp == 1 && player.hp > player.previous.hp) {
                        return 1;
                    } else {
                        return 0;
                    }
                }
            }
            return 0;
        },
        logTarget: 'player',
        content() {
            'step 0';
            player.randomGain(trigger.player, true);
            ('step 1');
            let card = game.createCard({ name: trigger.card.name, suit: trigger.card.suit, number: trigger.card.number, nature: trigger.card.nature });
            trigger.player.useCard(card, trigger.targets);
            trigger.player.addTempSkill('mx_niuqu2');
        },
    },
