            event.count--;
            if (
                !game.hasPlayer(function (current) {
                    const ejs = current.getCards('ej', function (card) {
                        return !event.cards.includes(card);
                    });
                    for (const i of ejs) {
                        if (
                            game.hasPlayer(function (current2) {
                                return current != current2 && !current2.isMin() && ((get.position(i) == 'e' && current2.isEmpty(get.subtype(i))) || (get.position(i) == 'j' && !current2.hasJudge(i)));
                            })
                        ) {
                            return true;
                        }
                    }
                })
            ) {
                event.finish();
                return;
            }
            let next = player.chooseTarget(2, function (card, player, target) {
                if (ui.selected.targets.length) {
                    const from = ui.selected.targets[0];
                    if (target.isMin()) {
                        return false;
                    }
                    const ejs = from.getCards('ej', function (card) {
                        return !event.cards.includes(card);
                    });
                    for (const i of ejs) {
                        if ((get.position(i) == 'e' && target.isEmpty(get.subtype(i))) || (get.position(i) == 'j' && !target.hasJudge(i))) {
                            return true;
                        }
                    }
                    return false;
                } else {
                    return (
                        target.countCards('ej', function (card) {
                            return !event.cards.includes(card);
                        }) > 0
                    );
                }
            });
            next.set('ai', function (target) {
                let att = get.attitude(player, target);
                const sgnatt = get.sgn(att);
                if (ui.selected.targets.length == 0) {
                    if (att > 0) {
                        if (
                            target.countCards('e', function (card) {
                                return (
                                    get.value(card, target) < 0 &&
                                    !event.cards.includes(card) &&
                                    game.hasPlayer(function (current) {
                                        return current != target && ((get.position(card) == 'e' && current.isEmpty(get.subtype(card))) || (get.position(card) == 'j' && !current.hasJudge(card))) && get.effect(current, card, player, player) < 0;
                                    })
                                );
                            }) > 0
                        ) {
                            return 9;
                        }
                    } else if (att < 0) {
                        if (
                            game.hasPlayer(function (current) {
                                if (current != target && get.attitude(player, current) > 0) {
                                    const ejs = target.getCards('ej', function (card) {
                                        return !event.cards.includes(card);
                                    });
                                    for (const i of ejs) {
                                        if (get.value(i, target) > 0 && ((get.position(i) == 'e' && current.isEmpty(get.subtype(i))) || (get.position(i) == 'j' && !current.hasJudge(i))) && get.effect(current, i, player, current) > 0) {
                                            return true;
                                        }
                                    }
                                }
                            })
                        ) {
                            return -att;
                        }
                    }
                    return 0;
                }
                const ejs = ui.selected.targets[0].getCards('ej', function (card) {
                    return !event.cards.includes(card);
                });
                let i;
                const att2 = get.sgn(get.attitude(player, ui.selected.targets[0]));
                for (const i of ejs) {
                    if (sgnatt != 0 && att2 != 0 && sgnatt != att2 && get.sgn(get.value(i, ui.selected.targets[0])) == -att2 && get.sgn(get.effect(target, i, player, target)) == sgnatt && target.isEmpty(get.subtype(i))) {
                        return Math.abs(att);
                    }
                }
                if (i == ejs.length) {
                    return 0;
                }
                return -att * get.attitude(player, ui.selected.targets[0]);
            });
