                        if (att > 0 || eff2 > 0) {
                            if (cards.length <= 5) {
                                cards = 5 - cards.length;
                            } else {
                                beginInd = 5;
                                endInd = 5;
                            }
                        } else {
                            if (get.value(cards, target) <= 5 && !target.isZhu) {
                                if (eff > 0 && Math.random() < 0.65) {
                                    beginInd = 0;
                                    endInd = 1;
                                }
                            }
                        }
