                const hp = player.hp;
                let card =
                    player.countCards('h', { name: 'shan' }) +
                    player.countCards('h', function (card) {
                        return get.tag(card, 'save');
                    });
                let num =
                    (game.countPlayer() -
                        game.countPlayer(function (current) {
                            return player.getFriends().includes(current) || current.isTurnedOver();
                        })) /
                    game.countPlayer();
                if (hp > 3) {
                    if (hp > 5) {
                        return '3';
                    }
                    if (num >= 0.5 && card > 0) {
                        return ['1', '2'].randomGet();
                    }
                    if (num >= 0.5) {
                        return '1';
                    }
                    if (num < 0.5 && card > 1) {
                        return '3';
                    }
                    return '2';
                }
                if (hp < 3 && card == 0) {
                    return '取消';
                }
                return '1';
