    mx_guangmang: {
        audio: 'ext:梦隐/Skill dubbing:2',
        trigger: {
            player: 'damageBegin',
        },
        filter(event, player) {
            return event.source && event.source != player && event.source.countCards('he') > 0 && event.num > 0;
        },
        content() {
            'step 0';
            event.num = Math.min(trigger.num, 9);
            ('step 1');
            let target = trigger.source;
            let num = player.countCards('e');
            let nh = target.countCards('e');
            const numh = player.countCards('h');
            const nhh = target.countCards('h');
            player.addTempSkill('mx_guangmang2', { player: 'mx_guangmangAfter' });
            player.chooseControl('手牌', '装备区', '取消').ai = function () {
                if (get.attitude(player, target) > 0) {
                    if (target.hasSkillTag('receiveEquip') || (target.hasSkillTag('noe') && nh > 1 && num < 3)) {
                        return '装备区';
                    }
                    if (target.isDamaged() && nh < 3 && num < 2 && target.getEquip('baiyin')) {
                        return '装备区';
                    }
                    if (nh < 2 && num < 3 && player.getEquip('baiyin')) {
                        return '装备区';
                    }
                    if (numh < 3 && !player.countCards('h', { name: 'tao' }) && target.hasSkillTag('noh') && nhh < 3) {
                        return '手牌';
                    }
                } else {
                    if (nh < 1) {
                        return '手牌';
                    }
                    if (nhh < 1) {
                        return '装备区';
                    }
                    if (target.hasSkillTag('receiveEquip') || target.hasSkillTag('noe')) {
                        return '手牌';
                    }
                    if (!target.hasSkillTag('receiveEquip') && !target.hasSkillTag('noe')) {
                        if (target.isDamaged() && target.getEquip('baiyin') && nh < 3) {
                            return '手牌';
                        }
                        if (nh > 0 && num < 1) {
                            return '装备区';
                        }
                        if (nh - num > 2) {
                            return '装备区';
                        }
                        if (player.getEquip('baiyin') && player.isDamaged() && num < 3) {
                            return '装备区';
                        }
                        return '手牌';
                    }
                    if (target.hasSkillTag('noh') && nhh < 3) {
                        return '手牌';
                    }
                    if (!target.hasSkillTag('noh')) {
                        const nk = game.countPlayer(function (current) {
                            return current.countCards('h') < 1;
                        });
                        if (nk > 1 && numh < 4) {
                            return '手牌';
                        }
                        if (numh < 1 && nhh > 0) {
                            return '手牌';
                        }
                        if (nhh - numh > 3) {
                            return '手牌';
                        }
                    }
                }
                return '取消';
            };
            ('step 2');
            if (result.control == '取消') {
                event.finish();
            }
            if (result.control == '手牌') {
                let card = player.getCards('h');
                const card1 = trigger.source.getCards('h');
                player.discard(card);
                player.draw();
                trigger.source.discard(card1);
            }
            if (result.control == '装备区') {
                let card = player.getCards('e');
                const card1 = trigger.source.getCards('e');
                player.discard(card);
                trigger.source.draw();
                trigger.source.discard(card1);
            }
            ('step 3');
            event.num--;
            ('step 4');
            if (event.num > 0) {
                event.goto(1);
            }
        },
        ai: {
            threaten: 20,
            expose: 0.3,
            maixie_defend: true,
            effect: {
                target(card, player, target) {
                    let num = player.countCards('e');
                    let nh = target.countCards('e');
                    const numh = player.countCards('h');
                    const nhh = target.countCards('h');
                    const nk = game.countPlayer(function (current) {
                        return current.countCards('h') < 1;
                    });
                    if (player.countCards('he') > 0 && get.tag(card, 'damage')) {
                        if (player.hasSkillTag('jueqing', false, target)) {
                            return [1, -1.5];
                        }
                        if (get.attitude(target, player) < 0) {
                            return [0.1, 1];
                        }
                        if (get.attitude(target, player) < 0 && numh - nhh > 2) {
                            return [-1, 0.5];
                        }
                        if (get.attitude(target, player) < 0 && num - nh > 2) {
                            return [-1, 0.5];
                        }
                        if (get.attitude(target, player) < 0 && nk > 1 && nhh < 4) {
                            return [-6, 1];
                        }
                    }
                },
            },
        },
    },
