    mx_guaili: {
        audio: 'ext:梦隐/Skill dubbing:2',
        enable: 'phaseUse',
        usable: 1,
        filter(event, player) {
            return game.hasPlayer(function (current) {
                return current != player && player.canUse({ name: 'sha' }, current);
            });
        },
        filterTarget(card, player, target) {
            const length = ui.selected.cards.length;
            if (get.distance(player, target, 'attack') > 1) {
                return false;
            }
            return (length == 0 || length == 2) && player != target && player.canUse({ name: 'sha' }, target);
        },
        check(card) {
            return 6 - get.value(card);
        },
        filterCard: true,
        selectCard: [0, 2],
        position: 'he',
        content() {
            'step 0';
            let list = ['弃牌阶段', '重铸全部的手牌'];
            event.list = list;
            if (cards.length == 2) {
                event.goto(2);
            } else {
                player
                    .chooseControl(event.list)
                    .set('ai', function (evt, player) {
                        const controls = _status.event.controls;
                        player = _status.event.player;
                        if (player.isTurnedOver()) {
                            return '弃牌阶段';
                        }
                        if (player.countCards('h', 'tao') >= 1) {
                            return '重铸全部的手牌';
                        }
                        return '弃牌阶段';
                    })
                    .set('prompt', '请选择一项');
            }
            ('step 1');
            if (result.control == '弃牌阶段') {
                player.phaseDiscard();
            } else if (result.control == '重铸全部的手牌') {
                let card = player.getCards('h');
                player.discard(card);
                player.draw(card.length);
            }
            ('step 2');
            player.addTempSkill('mx_guaili2');
            player.storage.mx_guaili = target;
            player.useCard({ name: 'sha' }, target, false);
            player.chooseUseTarget(false, { name: 'wanjian' });
        },
        ai: {
            order: 4,
            result: {
                target(player, target) {
                    if (player.countCards('he') <= 2 || !player.countCards('he', 'tao')) {
                        if (player.hp < 2) {
                            return 0;
                        }
                        if (target.hp >= player.hp) {
                            return 0;
                        }
                    }
                    return get.damageEffect(target, player);
                },
            },
        },
    },
