    mx_yingxiongsuzao: {
        audio: 'ext:梦隐/Skill dubbing:2',
        usable: 1,
        trigger: {
            global: 'phaseDrawBegin',
        },
        filter(event, player) {
            return event.player.isFriendsOf(player) && player.hp == _status.currentPhase.getAttackRange();
        },
        check(event, player) {
            const friends = game.countPlayer(function (current) {
                return get.attitude(player, current) > 0;
            });
            const enemies = game.countPlayer(function (current) {
                return get.attitude(player, current) < 0;
            });
            const neutral = game.countPlayer(function (current) {
                return get.attitude(player, current) == 0;
            });
            return friends + neutral * 0.6 + enemies * 0.3 + 0.1 >= event.num;
        },
        content() {
            'step 0';
            event.current = player.next;
            event.suits = [];
            event.cards = [];
            ('step 1');
            player.line(event.current, 'red');
            event.current.draw(2);
            let str = '请弃置一张手牌';
            event.current
                .chooseToDiscard('h', 1, true)
                .set('ai', function (card) {
                    let att = get.attitude(_status.event.player, player);
                    let base = 7;
                    const suits = _status.event.parent.suits;
                    if (att > 1 && !suits.includes(card.suit)) {
                        base += 3;
                    }
                    if (att < 0 && suits.includes(card.suit)) {
                        base -= 2;
                    }
                    return base - get.value(card);
                })
                .set('prompt', str);
            ('step 2');
            if (result.cards?.length) {
                event.suits.add(result.cards[0].suit);
                event.cards.add(result.cards[0]);
            }
            if (event.current != player) {
                event.current = event.current.next;
                event.goto(1);
            }
            ('step 3');
            if (event.suits.length == 0) {
                event.finish();
            } else {
                let cards = event.cards.filterInD('d');
                if (cards.length == 0) {
                    event._result = {
                        bool: false,
                    };
                    return;
                }
                let dialog = ui.create.dialog('英雄塑造');
                dialog.add('获得其中的至多' + get.cnNumber(event.suits.length) + '张牌');
                dialog.add(cards);
                player
                    .chooseButton(dialog, [1, event.suits.length])
                    .set('ai', function (button) {
                        let card = button.link;
                        if (_status.event.bool) {
                            return get.value(card) - 1;
                        }
                        let base = 3;
                        const cardsx = player.getCards('hs');
                        for (const i of ui.selected.buttons) {
                            if (i.link.name == card.name) {
                                base++;
                            }
                        }
                        for (const i of cardsx) {
                            if (i.name == card.name) {
                                base++;
                            }
                        }
                        return (get.value(card) * 3) / base - 3.5;
                    })
                    .set('bool', trigger.numFixed);
            }
            ('step 4');
            if (!trigger.numFixed) {
                trigger.num = event.suits.length;
            }
            if (result.bool) {
                player.gain(result.links, 'gain');
                trigger.num += result.links.length;
            }
        },
        action_tag: {
            overall: 1.5,
            draw: 1,
            change: 1,
        },
    },
    mx_lixiangxiang: {
        audio: 'ext:梦隐/Skill dubbing:2',
        trigger: {
            player: ['mx_menghuanBegin', 'mx_yingxiongsuzaoBegin', 'damageBegin'],
        },
        filter(event, player) {
            return player.countCards('h', function (card) {
                let type = get.type(card, player);
                return (type == 'basic' || type == 'trick') && get.tag(card, 'damage') > 0;
            });
        },
        content() {
            'step 0';
            player.useSkill('mx_lixiangxiang2');
            player
                .chooseTarget(lib.filter.notMe, get.prompt('mx_lixiangxiang'), '选择目标')
                .set(true)
                .set('ai', function (target) {
                    let player = _status.event.player,
                        cards = _status.event.aiCards;
                    let att = get.attitude(player, target);
                    if (att <= 0) {
                        return 0;
                    }
                    if (target.hasSkillTag('nogain')) {
                        att /= 100;
                    }
                    let num = 0.1;
                    for (let i of cards) {
                        num += Math.max(0, target.getUseValue(card));
                    }
                    return num * att;
                })
                .set(
                    'aiCards',
                    player.getCards('h', function (card) {
                        let type = get.type(card, player);
                        return (type == 'basic' || type == 'trick') && get.tag(card, 'damage') > 0;
                    }),
                );
            ('step 1');
            if (result.bool) {
                let target = result.targets[0];
                player.give(
                    player.getCards('h', function (card) {
                        let type = get.type(card, player);
                        return (type == 'basic' || type == 'trick') && get.tag(card, 'damage') > 0;
                    }),
                    target,
                    'give',
                );
            }
        },
    },
