    //当你使用【杀】造成伤害后,若当前回合角色没有【闪】,你可以令攻击范围内的其他角色各展示一张牌,你选择一项:❶获得展示的牌并翻面,依次对共计两名随机敌方角色各造成2点寒冰伤害;❷任意替换展示的牌与你的手牌
    mx_zhenyinzhan: {
        trigger: {
            player: 'shaDamage',
        },
        filter(event, player) {
            if (_status.currentPhase.countCards('h', { name: 'shan' })) {
                return false;
            }
            return game.hasPlayer(function (current) {
                return player.inRange(current) && current.countCards('he') > 0;
            });
        },
        async content(event, trigger, player) {
            //QQQ
            const npcs = game.players.filter((q) => player.inRange(q) && q.countCards('he') > 0);
            const list = [];
            for (let i = 0; i < npcs.length; i++) {
                const npc = npcs[i];
                const { cards } = await npc
                    .chooseCard('he', true)
                    .set('ai', (c) => 6 - get.value(c))
                    .forResult();
                if (cards?.length) {
                    list.push(cards[0]);
                    npc.showCards(cards);
                } else {
                    npcs.splice(i, 1); // 因为移除了一个元素,所以需要将索引减1以确保不会跳过下一个元素
                    i--;
                }
            }
            if (list.length) {
                const { control } = await player
                    .chooseControl('获得', '替换')
                    .set('ai', (e, p) => ['获得', '替换'].randomGet())
                    .forResult();
                if (control == '获得') {
                    player.gain(list, 'gain2');
                    player.turnOver();
                    const enemy = game.players.filter((q) => q.isEnemiesOf(player)).randomGets(2);
                    for (let i of enemy) {
                        i.damage(2, 'ice');
                    }
                } else {
                    const cards = [];
                    for (let i of list) {
                        cards.push([`${get.translation(get.owner(i))}的牌`, [i]]);
                    }
                    if (player.countCards('he')) {
                        cards.push(['你的牌', player.getCards('he')]);
                    }
                    const { moved } = await player
                        .chooseToMove()
                        .set('list', cards)
                        .set('prompt', '替换牌')
                        .set('filterMove', function (from, to) {
                            return typeof to != 'number';
                        })
                        .set('processAI', function () {
                            const pai = list.slice();
                            if (player.countCards('he')) {
                                pai.addArray(player.getCards('he'));
                            }
                            pai.sort((a, b) => get.value(b) - get.value(a));
                            const sort = npcs.map((q) => {
                                if (q.isFriendsOf(player)) {
                                    return pai.shift();
                                }
                                return pai.pop();
                            });
                            sort.push(pai);
                            return sort;
                        })
                        .forResult(); //给别人观星
                    if (moved && moved[0]) {
                        const num = moved.length;
                        for (let i = 0; i < num; i++) {
                            if (i != num - 1) {
                                npcs[i].gain(moved[i], 'gain2');
                            } else {
                                player.gain(moved[i], 'gain2');
                            }
                        }
                    }
                }
            }
        },
    },
