        selectCard: -1,
        filterCard() {
            return false;
        },
        usable: 1,
        filter(event, player) {
            return game.hasPlayer((target) => lib.skill.mx_beiluoboge.filterTarget(null, player, target));
        },
        filterTarget(card, player, target) {
            const isMin = target.isMinHandcard();
            const isMax = target.isMaxHandcard();
            const isMinTarget = game.findPlayer((Target) => Target != target && Target.isMinHandcard());
            const isMaxTarget = game.findPlayer((Target) => Target != target && Target.isMaxHandcard());
            let hs = target.countCards('h');
            if (isMin && isMaxTarget) {
                return isMaxTarget.countCards('h') - hs > 0;
            }
            if (isMax && isMinTarget) {
                return isMinTarget.countCards('h') - hs < 0;
            }
            return false;
        },
        content() {
            let num = lib.skill.mx_beiluoboge.ai.result.target(player, target);
            if (num > 0) {
                target.addTempSkill('mx_beiluoboge2', { player: 'mx_beiluoboge2After' });
                target.draw(num);
            } else if (num < 0) {
                num = -num;
                let count = target.getCards('h', function (i) {
                    return lib.filter.cardDiscardable(i, target, event.name);
                });
                if (count.length <= num) {
                    player.draw();
                    target.discard(count);
                } else {
                    player.draw();
                    target.chooseToDiscard('h', num, true, lib.filter.cardDiscardable);
                }
            }
        },
