    mx_bingjihuanghou: {
        audio: 'ext:梦隐/Skill dubbing:2',
        trigger: {
            target: 'useCardToTargeted',
        },
        filter(event, player) {
            if (player == event.player) {
                return false;
            }
            if (!player.countCards('h', { type: 'trick' })) {
                return false;
            }
            let card = event.card;
            if (get.type(card) == 'basic' || get.type(card) == 'trick') {
                return true;
            }
            return false;
        },
        prompt(event, player) {
            return '发动此技能？';
        },
        check(event, player) {
            if (event.parent.excluded.includes(player)) {
                return false;
            }
            if (get.effect(player, event.card, event.player, player) >= 0) {
                return false;
            }
            let card = event.card;
            const id = player.playerid;
            const map = event.parent.customArgs;
            let need = 1;
            if (get.tag(card, 'respondSha')) {
                if (map[id] && typeof map[id].shaReq == 'number') {
                    need = map[id].shaReq;
                }
                if (
                    player.countCards('h', {
                        name: 'sha',
                    }) < need
                ) {
                    return true;
                }
            } else if (get.tag(card, 'respondShan')) {
                if (map[id] && typeof map[id].shanRequired == 'number') {
                    need = map[id].shanRequired;
                }
                if (
                    player.countCards('h', {
                        name: 'shan',
                    }) < need
                ) {
                    return true;
                }
            } else if (get.tag(card, 'damage') && card.name != 'huogong') {
                return true;
            }
            return false;
        },
        content() {
            'step 0';
            player.chooseToDiscard('请弃置一张普通锦囊牌', 1, 'h', true, { type: 'trick' });
            ('step 1');
            trigger.parent.excluded.add(player);
            ('step 2');
            player
                .chooseTarget(1, get.prompt2('mx_bingjihuanghou'), function (card, player, target) {
                    return target.hp != target.countCards('h');
                })
                .set('ai', function (target) {
                    let base = 1;
                    if (target == player) {
                        base = target.hp > target.countCards('h') ? 2.1 : 0;
                    } else if (target.countCards('h') < target.hp) {
                        base = 2 / target.hp;
                    } else {
                        base = -4 / (Math.max(target.hp, 0.5) * target.countCards('h'));
                    }
                    let num = target.countCards('h') - target.hp;
                    return base * get.attitude(player, target);
                });
            ('step 3');
            if (result.bool && result.targets.length) {
                let target = result.targets[0];
                player.line(target, 'red');
                game.log('mx_bingjihuanghou', player, '令', target, target.countCards('h') < target.hp ? '摸两张牌' : '弃置四张手牌');
                if (target.countCards('h') < target.hp) {
                    target.draw(2);
                } else {
                    player.phaseUse();
                    target.turnOver(true);
                    target.addTempSkill('mx_bingjihuanghou2', { player: 'recoverAfter' });
                    target.chooseToDiscard(4, 'h', true);
                }
            }
        },
        ai: {
            threaten(viewer, player) {
                if (player.countCards('h') < player.hp - 1) {
                    return 0.7;
                }
            },
        },
    },
    mx_bingjihuanghou2: {
        mod: {
            cardEnabled(card, player) {
                if (get.type(card, 'trick') == 'trick') {
                    return false;
                }
            },
            cardRespondable(card, player) {
                if (get.type(card, 'trick') == 'trick') {
                    return false;
                }
            },
            cardSavable(card, player) {
                if (get.type(card, 'trick') == 'trick') {
                    return false;
                }
            },
        },
    },
