    mx_dieyinzhishi: {
        srlose: true,
        audio: 'ext:梦隐/Skill dubbing:2',
        trigger: {
            global: 'judgeBegin',
        },
        content() {
            'step 0';
            if (player.isUnderControl()) {
                game.modeSwapPlayer(player);
            }
            let cards = get.cards(game.players.length);
            event.cards = cards;
            const switchToAuto = function () {
                _status.imchoosing = false;
                if (event.dialog) {
                    event.dialog.close();
                }
                if (event.control) {
                    event.control.close();
                }
                const target = trigger.player;
                const att = get.attitude(player, target);
                const top = [],
                    bottom = cards;
                for (const i of target.getCards('j')) {
                    const judge = get.judge(i);
                    bottom.sort((a, b) => (judge(b) - judge(a)) * att); //态度大于0价值高的牌放前面
                    if (bottom.length) {
                        top.push(bottom.shift());
                    }
                }
                bottom.sort((a, b) => (get.value(b) - get.value(a)) * att); //态度大于0价值高的牌放前面
                while (bottom.length) {
                    top.push(bottom.shift());
                }
                top.reverse();
                for (const i of top) {
                    ui.cardPile.insertBefore(i, ui.cardPile.firstChild);
                }
                for (const i of bottom) {
                    ui.cardPile.appendChild(i);
                }
                player.popup(get.cnNumber(top.length) + '上' + get.cnNumber(bottom.length) + '下');
                game.log(player, '将' + get.cnNumber(top.length) + '张牌置于牌堆顶');
            };
            const chooseButton = function (online, player, cards) {
                let event = _status.event;
                player = player || event.player;
                cards = cards || event.cards;
                event.top = [];
                event.bottom = [];
                event.status = true;
                event.dialog = ui.create.dialog('将其中的任意张牌置于牌堆顶', cards);
                event.switchToAuto = function () {
                    event._result = 'ai';
                    event.dialog.close();
                    event.control.close();
                    _status.imchoosing = false;
                };
                event.control = ui.create.control('ok', 'pileTop', 'pileBottom', function (link) {
                    let event = _status.event;
                    if (link == 'ok') {
                        if (online) {
                            event._result = {
                                top: [],
                                bottom: [],
                            };
                            for (const i of event.top) {
                                event._result.top.push(i.link);
                            }
                            for (const i of event.bottom) {
                                event._result.bottom.push(i.link);
                            }
                        } else {
                            let i;
                            for (const i of event.top) {
                                ui.cardPile.insertBefore(i.link, ui.cardPile.firstChild);
                            }
                            for (const i of event.bottom) {
                                ui.cardPile.appendChild(i.link);
                            }
                            for (const i of event.dialog.buttons) {
                                if (i.classList.contains('glow') == false && i.classList.contains('target') == false) {
                                    ui.cardPile.appendChild(i.link);
                                }
                            }
                            player.popup(get.cnNumber(event.top.length) + '上' + get.cnNumber(event.cards.length - event.top.length) + '下');
                            game.log(player, '将' + get.cnNumber(event.top.length) + '张牌置于牌堆顶');
                        }
                        event.dialog.close();
                        event.control.close();
                        game.resume();
                        _status.imchoosing = false;
                    } else if (link == 'pileTop') {
                        event.status = true;
                        event.dialog.content.childNodes[0].innerHTML = '按顺序选择置于牌堆顶的牌';
                    } else {
                        event.status = false;
                        event.dialog.content.childNodes[0].innerHTML = '按顺序选择置于牌堆底的牌';
                    }
                });
                for (const i of event.dialog.buttons) {
                    i.classList.add('selectable');
                }
                event.custom.replace.button = function (link) {
                    let event = _status.event;
                    if (link.classList.contains('target')) {
                        link.classList.remove('target');
                        event.top.remove(link);
                    } else if (link.classList.contains('glow')) {
                        link.classList.remove('glow');
                        event.bottom.remove(link);
                    } else if (event.status) {
                        link.classList.add('target');
                        event.top.unshift(link);
                    } else {
                        link.classList.add('glow');
                        event.bottom.push(link);
                    }
                };
                event.custom.replace.window = function () {
                    for (const i of _status.event.dialog.buttons) {
                        i.classList.remove('target');
                        i.classList.remove('glow');
                        _status.event.top.length = 0;
                        _status.event.bottom.length = 0;
                    }
                };
                game.pause();
                game.countChoose();
            };
            event.switchToAuto = switchToAuto;
            if (event.isMine()) {
                chooseButton();
                event.finish();
            } else if (event.isOnline()) {
                event.player.send(chooseButton, true, event.player, event.cards);
                event.player.wait();
                game.pause();
            } else {
                event.switchToAuto();
                event.finish();
            }
            ('step 1');
            if (event.result == 'ai' || !event.result) {
                event.switchToAuto();
            } else {
                const top = event.result.top || [];
                const bottom = event.result.bottom || [];
                for (const i of top) {
                    ui.cardPile.insertBefore(i, ui.cardPile.firstChild);
                }
                for (const i of bottom) {
                    ui.cardPile.appendChild(i);
                }
                if (Array.isArray(event.cards)) {
                    for (let i of event.cards) {
                        if (!top.includes(i) && !bottom.includes(i)) {
                            ui.cardPile.appendChild(i);
                        }
                    }
                }
                player.popup(get.cnNumber(top.length) + '上' + get.cnNumber(event.cards.length - top.length) + '下');
                game.log(player, '将' + get.cnNumber(top.length) + '张牌置于牌堆顶');
            }
        },
        ai: {
            threaten: 2,
        },
    },
