    mx_guangyingjichi: {
        audio: 'ext:梦隐/Skill dubbing:2',
        trigger: {
            global: 'useCardToTarget',
        },
        filter(event, player) {
            if (player == event.player) {
                if (!event.target.countCards('he')) {
                    return false;
                }
            } else if (!event.target.countCards('he') && !event.player.countCards('he')) {
                return false;
            }
            return event.card && event.card.name == 'sha' && player != event.target;
        },
        check(event, player) {
            if (player.countDisabled() == 5) {
                if (player.hp == 1) {
                    return false;
                }
            }
            if (get.attitude(player, event.target) < 0) {
                if (event.target.countCards('e')) {
                    return true;
                } else if (event.target.hp == 1) {
                    return true;
                }
            } else if (get.attitude(player, event.player) < 0) {
                if (event.player.countCards('e')) {
                    return true;
                } else if (event.target.countCards('h') == 1) {
                    return true;
                }
            }
            return false;
        },
        logTarget: 'player',
        content() {
            'step 0';
            if (player.countDisabled() > 4) {
                player.chooseUseTarget(false, { name: 'toulianghuanzhu' });
            } else {
                player.chooseToDisable();
            }
            ('step 1');
            player
                .chooseTarget('选择目标', true, function (card, player, target) {
                    return player != target && target.countCards('he') && (target == trigger.player || trigger.targets.includes(target));
                })
                .set('ai', function (target) {
                    if (get.attitude(_status.event.player, target) > 0) {
                        return 0;
                    }
                    return -1;
                });
            ('step 2');
            if (result.bool) {
                event.target = result.targets[0];
                player
                    .gainPlayerCard('he', event.target, true)
                    .set('ai', function (button) {
                        if (!_status.event.att) {
                            return 0;
                        }
                        if (get.position(button.link) == 'e') {
                            if (get.subtype(button.link) == 'equip2') {
                                return 2 * get.value(button.link);
                            }
                            return get.value(button.link);
                        }
                        return 1;
                    })
                    .set('att', get.attitude(player, event.target) <= 0);
            }
            ('step 3');
            if (result.links?.length) {
                if (get.subtype(result.links[0]) == 'equip1') {
                    player.enableEquip('equip1');
                }
                if (get.subtype(result.links[0]) == 'equip2') {
                    player.next.recover() && player.enableEquip('equip2');
                }
                if (get.subtype(result.links[0]) == 'equip3') {
                    player.enableEquip('equip3');
                }
                if (get.subtype(result.links[0]) == 'equip4') {
                    player.enableEquip('equip4');
                }
                if (get.subtype(result.links[0]) == 'equip5') {
                    player.next.draw() && player.enableEquip('equip5');
                }
                if (get.subtype(result.links[0]) == 'equip6') {
                    player.enableEquip('equip3');
                    player.enableEquip('equip4');
                }
            }
        },
    },
