    mx_dashe: {
        audio: 'ext:梦隐/Skill dubbing:2',
        enable: 'phaseUse',
        usable: 1,
        filter(event, player) {
            return player.countCards('he') && player.getStorage('mx_dashe_clear').length < 4;
        },
        onChooseToUse(event) {
            if (event.type == 'phase' && !game.online) {
                const map = {};
                event.player.getHistory('useCard', (evt) => {
                    let evtx = evt.getParent('phaseUse'),
                        suit = evt.card.suit;
                    if (!lib.suit.includes(suit)) {
                        return;
                    }
                    if (evtx != event.getParent('phaseUse')) {
                        return;
                    }
                    if (typeof map[suit] != 'number') {
                        map[suit] = 0;
                    }
                    map[suit]++;
                });
                event.set('mx_dashe_map', map);
            }
        },
        chooseButton: {
            dialog(event, player) {
                let str = get.translation('mx_dashe_info'),
                    str2 = '';
                if (event.mx_dashe_map) {
                    str2 = '<div class="text center">此阶段你使用过的花色数:</div>';
                    str2 += '<div class="text center">';
                    for (let suit of lib.suit) {
                        str2 += get.translation(suit) + ':' + get.cnNumber(event.mx_dashe_map[suit] || 0) + '张;';
                    }
                    str2 = str2.slice(0, str2.length - 1) + '</div>';
                }
                return ui.create.dialog('###灵裳重光·七九式掷祸大社###' + str, str2);
            },
            chooseControl(event, player) {
                let list = lib.suit.slice();
                list.removeArray(player.getStorage('mx_dashe_clear'));
                list.push('cancel2');
                return list;
            },
            check(event, player) {
                const map = event.mx_dashe_map;
                let suit = lib.suit
                    .filter((i) => !player.getStorage('mx_dashe_clear').includes(i))
                    .sort((a, b) => {
                        return map[b] - map[a];
                    })[0];
                if (map[suit] == 0) {
                    return 'cancel2';
                }
                return suit;
            },
            backup(result, player) {
                return {
                    audio: 'ext:梦隐/Skill dubbing:2',
                    filterCard: true,
                    selectCard: 1,
                    position: 'he',
                    suit: result.control,
                    check(card) {
                        let suit = lib.skill.mx_dashe.suit;
                        if (card.suit == suit) {
                            return 10 - get.value(card);
                        }
                        return 6 - get.value(card);
                    },
                    content() {
                        'step 0';
                        let suit = lib.skill.mx_dashe_backup.suit,
                            num = 0;
                        player.popup(suit + 2);
                        player.addTempSkill('mx_dashe_clear', 'phaseUseAfter');
                        player.markAuto('mx_dashe_clear', [suit]);
                        player.getHistory('useCard', (evt) => {
                            const evtx = evt.getParent('phaseUse'),
                                suitx = evt.card.suit;
                            if (!evtx || evtx != event.getParent('phaseUse') || suit != suitx) {
                                return false;
                            }
                            num++;
                        });
                        if (num > 0) {
                            player.randomGain(player.previous, num, 'hej', true) && player.chooseUseTarget(false, true, { name: 'chuqibuyi', color: 'red', suit: 'diamond' }) && player.gain(game.createCard('chuqibuyi'), 'gain2');
                        }
                        ('step 1');
                        if (cards[0].suit == lib.skill.mx_dashe_backup.suit) {
                            delete player.getStat('skill').mx_dashe;
                        }
                    },
                    ai: {
                        result: {
                            player: 1,
                        },
                    },
                };
            },
            prompt: () => '灵裳重光·七九式掷祸大社<br/><br/>请弃置一张牌',
        },
        ai: {
            order: 2,
            result: {
                player: 1,
            },
        },
        subSkill: {
            backup: {},
            clear: {
                charlotte: true,
            },
        },
    },
