    mx_lunwuqu: {
        audio: 'ext:梦隐/Skill dubbing:2',
        enable: 'phaseUse',
        filterCard: true,
        selectCard: 3,
        position: 'e',
        filter(event, player) {
            return player.isMaxHandcard(true) && player.countCards('e') >= 3;
        },
        filterTarget(card, player, target) {
            return target != player && target.hp > player.hp;
        },
        line: 'fire',
        check(card) {
            return 8 - get.value(card);
        },
        content() {
            'step 0';
            let num = Math.ceil(player.getAttackRange() / 2);
            target.damage(3);
            if (!target.countCards('h', { type: 'basic' })) {
                player.draw();
            }
            ('step 1');
            event.targets = game
                .filterPlayer(function (current) {
                    return get.distance(target, current) <= num && current != target && current != player;
                })
                .sortBySeat(target);
            ('step 2');
            if (event.targets.length) {
                event.targets.shift().randomDiscard(false);
                event.redo();
            }
        },
        ai: {
            order: 6,
            result: {
                player(player, target) {
                    if (get.damageEffect(target, player, player, 'thunder') > 0) {
                        if (target == player.storage.yuexing2) {
                            return 10;
                        }
                        let num =
                            1 +
                            game.countPlayer(function (current) {
                                if (get.distance(target, current) <= 1 && current != player && current != target) {
                                    return -get.sgn(get.attitude(player, current));
                                }
                            });
                        if (target.hp == 1) {
                            num += 2;
                        }
                        if (target.hp < player.hp) {
                            num += 0.5;
                        }
                        if (player.needsToDiscard()) {
                            num += 0.1;
                        }
                        return num;
                    }
                },
            },
        },
    },
    mx_zhenhunqu: {
        audio: 'ext:梦隐/Skill dubbing:2',
        trigger: {
            global: 'damageEnd',
        },
        filter(event, player) {
            return event.num > 0 && player != event.player && event.player.isFriendsOf(player);
        },
        content() {
            'step 0';
            event.num = Math.min(trigger.num, 9);
            ('step 1');
            event.cards = get.cards(3);
            game.cardsGotoOrdering(event.cards);
            event.videoId = lib.status.videoId++;
            game.broadcastAll(
                function (player, id, cards) {
                    let str;
                    if (player == game.me && !_status.auto) {
                        str = '获得其中类别均不相同的牌';
                    } else {
                        str = '镇魂曲';
                    }
                    let dialog = ui.create.dialog(str, cards);
                    dialog.videoId = id;
                },
                player,
                event.videoId,
                event.cards,
            );
            event.time = get.utc();
            game.addVideo('showCards', player, ['镇魂曲', get.cardsInfo(event.cards)]);
            game.addVideo('delay', null, 2);
            ('step 2');
            let next = player.chooseButton([0, 5], true);
            next.set('dialog', event.videoId);
            next.set('filterButton', function (button) {
                for (const i of ui.selected.buttons) {
                    if (get.type(button.link, 'trick') == get.type(i.link, 'trick')) {
                        return false;
                    }
                }
                return true;
            });
            next.set('ai', function (button) {
                return get.value(button.link, _status.event.player);
            });
            ('step 3');
            if (result.bool && result.links) {
                event.cards2 = result.links;
            } else {
                event.cards2 = [];
            }
            ('step 4');
            game.broadcastAll('closeDialog', event.videoId);
            let cards2 = event.cards2;
            if (cards2.length) {
                trigger.player.changeHujia();
                player.gain(cards2, 'log', 'gain');
                event.cards.removeArray(cards2);
            }
            if (!event.cards.length) {
                event.goto(7);
            }
            ('step 5');
            player
                .chooseTarget(function (card, player, target) {
                    return target != player;
                })
                .set('ai', function (target) {
                    return get.attitude(player, target) / Math.sqrt(1 + target.countCards('h'));
                })
                .set('createDialog', ['令一名其他角色获得' + get.translation(event.cards) + '？', event.cards]);
            ('step 6');
            if (result.bool) {
                player.line(result.targets);
                result.targets[0].addTempSkill('mx_zhenhunqu2', { player: 'mx_zhenhunqu2After' });
                result.targets[0].gain(event.cards, 'log', 'gain');
            }
            ('step 7');
            event.num--;
            if (event.num > 0) {
                player.chooseBool('发动此技能？').set('frequentSkill', 'mx_zhenhunqu');
            } else {
                event.finish();
            }
            ('step 8');
            if (result.bool) {
                event.goto(1);
            }
        },
        ai: {
            maixie: true,
            maixie_hp: true,
            effect: {
                target(card, player, target) {
                    if (player.hasSkillTag('jueqing', false, target)) {
                        return [1, -1];
                    }
                    if (get.tag(card, 'damage')) {
                        return [1, 0.55];
                    }
                },
            },
        },
    },
