    mx_xingzhituxi: {
        audio: 'ext:梦隐/Skill dubbing:2',
        trigger: {
            player: 'damageBegin',
        },
        filter(event, player) {
            if (event.num <= 0) {
                return false;
            }
            if (get.itemtype(event.cards) != 'cards') {
                return false;
            }
            if (event.card.isCard) {
                if (get.position(event.cards[0], true) == 'o') {
                    return true;
                }
            }
            return false;
        },
        content() {
            'step 0';
            let num = Math.floor(game.roundNumber / 2);
            player.useSkill('mx_xingzhituxi2');
            player.drawTo(num);
            ('step 1');
            const col = get.color(trigger.cards[0]);
            event.str = col == 'red' ? 'lebu' : 'fulei';
            player.chooseTarget(
                '你可以将' + get.translation(trigger.cards[0]) + '当' + get.translation(event.str) + '置入一名角色的判定区',
                1,
                function (card, player, target) {
                    return !target.hasJudge(event.str);
                },
                function (target) {
                    let eff = get.effect(target, { name: event.str }, player, player);
                    return eff;
                },
            );
            ('step 2');
            if (result.bool) {
                let next = player.useCard({ name: event.str }, trigger.cards, result.targets[0]);
                next.animate = false;
                next.audio = false;
            }
        },
        ai: {
            maixie: true,
            maixie_hp: true,
            effect: {
                target(card, player, target) {
                    if (get.tag(card, 'damage')) {
                        if (player.hasSkillTag('jueqing', false, target)) {
                            return [1, -2];
                        }
                        if (!target.hasFriend()) {
                            return;
                        }
                        return [1, 1.5];
                    }
                },
            },
        },
        _priority: 200,
    },
